To solve this problem, you need to implement a **Global Tooltip Provider**.

Since Next.js components are isolated, you cannot rely on local state (like `useState` inside the component) to track which tooltip is open. Instead, you will create a Context that lives at the top of your application (usually in `_app.tsx` or a layout wrapper) and pass the state of "all open tooltips" down to your components.

Here is a complete, copy-pasteable solution.

### 1. Create the Context and Logic

Create a file named `tooltip-context.tsx`. This handles the logic of opening, closing, and tracking the active tooltip.

```tsx
'use client'; // Required for Next.js App Router

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of our data
interface TooltipContextType {
  openTooltip: (id: string, content: string, position?: 'top' | 'bottom' | 'left' | 'right') => void;
  closeTooltip: (id: string) => void;
  closeAllTooltips: () => void;
  isOpen: (id: string) => boolean;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

// We use a ref to store the list of open tooltips to avoid re-renders on every open/close
// unless the specific tooltip changes.
const useTooltips = () => {
  const [openTooltips, setOpenTooltips] = useState<Record<string, { content: string; position: string }>>({});

  const openTooltip = useCallback((id: string, content: string, position: 'top' | 'bottom' | 'left' | 'right' = 'top') => {
    setOpenTooltips((prev) => ({
      ...prev,
      [id]: { content, position },
    }));
  }, []);

  const closeTooltip = useCallback((id: string) => {
    setOpenTooltips((prev) => {
      const { [id]: _, ...rest } = prev;
      return rest;
    });
  }, []);

  const closeAllTooltips = useCallback(() => {
    setOpenTooltips({});
  }, []);

  const isOpen = useCallback((id: string) => {
    return !!openTooltips[id];
  }, [openTooltips]);

  return {
    openTooltip,
    closeTooltip,
    closeAllTooltips,
    isOpen,
  };
};

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { openTooltip, closeTooltip, closeAllTooltips, isOpen } = useTooltips();

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, closeAllTooltips, isOpen }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

