### The Implementation

```jsx
import React, { useState } from 'react';
import { gql, useMutation } from '@apollo/client';

// 1. Define the GraphQL Mutation
// This defines the shape of the data you are sending and receiving.
const CREATE_USER_MUTATION = gql`
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      name
    }
  }
`;

export default function UserRegistrationForm() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // 2. The onSubmit Function
  const handleSubmit = async (e) => {
    // Prevent default form submission (page reload)
    e.preventDefault();

    // Get form data from the event target
    const formData = new FormData(e.target);

    // Convert FormData to a plain object
    const data = Object.fromEntries(formData.entries());

    try {
      setLoading(true);
      setError(null);

      // 3. Execute the GraphQL Mutation
      // We pass the 'data' object as variables
      const { data: mutationData } = await useMutation(CREATE_USER_MUTATION)({
        variables: {
          input: {
            email: data.email,
            name: data.name,
            // Add other fields here
          }
        }
      });

      // 4. Handle Success
      console.log('User created successfully:', mutationData.createUser);
      alert('Registration successful!');

      // Optional: Reset form
      e.target.reset();

    } catch (err) {
      // 5. Handle Errors
      console.error('GraphQL Error:', err);
      setError(err.message || 'An unexpected error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Create Account</h2>

      <div style={{ marginBottom: '1rem' }}>
        <label>Name</label>
        <input name="name" required />
      </div>

