Here are the two functions to pack and unpack the data.

### The Logic

1.  **Packing**: We iterate through the entities. For each entity, we shift the `id` and `size` into their respective bit positions (0-3 for ID, 4-6 for size) and combine them using bitwise OR. We then write the resulting 7-bit integer into the `Uint8Array` at the current offset.
2.  **Unpacking**: We read the `Uint8Array` as a `Uint8Array` (since 7 bits fits in a byte). We use bitwise masking (`& 0x0F` for 4 bits, `& 0x07` for 3 bits) and shifting (`>> 0`, `>> 4`) to extract the fields.

### The Code

```javascript
/**
 * Packs an array of entities into a Uint8Array (ArrayBuffer).
 * 
 * @param {Array} entities - Array of objects with { id, size }
 * @returns {Uint8Array} - The packed buffer
 */
function packEntities(entities) {
    if (!entities || entities.length === 0) {
        return new Uint8Array(0);
    }

    const buffer = new Uint8Array(entities.length);
    let offset = 0;

    for (const entity of entities) {
        // Ensure we have the required fields
        if (typeof entity.id !== 'number' || typeof entity.size !== 'number') {
            throw new Error("Entity must have numeric 'id' and 'size' fields");
        }

        // Pack into a 7-bit integer:
        // Bits 0-3: ID (4 bits)
        // Bits 4-6: Size (3 bits)
        const packedValue = (entity.id & 0x0F) | ((entity.size & 0x07) << 4);

        buffer[offset++] = packedValue;
    }

    return buffer;
}

/**
 * Unpacks a Uint8Array (ArrayBuffer) into an array of entities.
 * 
 * @param {Uint8Array} buffer - The packed buffer
 * @returns {Array} - Array of objects with { id, size }
 */
function unpackEntities(buffer) {
    const entities = [];

    // Iterate over every byte in the buffer
    for (let i = 0; i < buffer.length; i++) {
        const byte = buffer[i];

        // Extract fields using bitwise operations:
        // ID is in the lower 4 bits (mask 0x0F)
        // Size is in the upper 3 bits (mask 0x07) shifted right by 4
        const id = byte & 0x0F;
        const size = (byte >> 4) & 0x07;

        entities.push({ id, size });
    }

    return entities;
}

